"""restops: daily sales + food-cost tracker for small restaurants."""
import sys
from dataclasses import dataclass, field


@dataclass
class Item:
    name: str
    unit_cost: float
    stock: float
    reorder_at: float


@dataclass
class Day:
    date: str
    covers: int
    revenue: float
    food_cost: float

    @property
    def food_cost_pct(self):
        return 100 * self.food_cost / self.revenue if self.revenue else 0.0


@dataclass
class Restaurant:
    name: str
    items: dict = field(default_factory=dict)
    days: list = field(default_factory=list)

    def add_item(self, item):
        self.items[item.name] = item

    def use(self, name, qty):
        it = self.items[name]
        it.stock -= qty
        return it.stock <= it.reorder_at  # True => reorder alert

    def log_day(self, day):
        self.days.append(day)

    def weekly_report(self, last_n=7):
        recent = self.days[-last_n:]
        if not recent:
            return "No data yet."
        rev = sum(d.revenue for d in recent)
        fc = sum(d.food_cost for d in recent)
        covers = sum(d.covers for d in recent)
        pct = 100 * fc / rev if rev else 0
        alerts = [n for n, i in self.items.items() if i.stock <= i.reorder_at]
        lines = [
            f"{self.name} — last {len(recent)} days",
            f"  covers: {covers}  revenue: ${rev:,.2f}  avg check: ${rev/covers:,.2f}" if covers else "  no covers",
            f"  food cost: ${fc:,.2f} ({pct:.1f}% of revenue)",
            f"  target band 28-32%: {'OK' if 28 <= pct <= 32 else 'OUT OF BAND'}",
            f"  reorder now: {', '.join(alerts) if alerts else 'none'}",
        ]
        return "\n".join(lines)


def demo():
    r = Restaurant("Sample Family Kitchen")
    r.add_item(Item("rice (lb)", 0.90, 40, 10))
    r.add_item(Item("chicken thigh (lb)", 2.40, 25, 8))
    r.add_item(Item("cilantro (bunch)", 0.75, 6, 3))
    for i, (cov, rev, fc) in enumerate([(120, 1900, 560), (95, 1480, 430), (140, 2250, 690),
                                        (110, 1720, 520), (160, 2600, 790), (180, 2950, 900),
                                        (90, 1350, 400)], start=1):
        r.log_day(Day(f"day{i}", cov, rev, fc))
    r.use("chicken thigh (lb)", 12)
    print(r.weekly_report())


if __name__ == "__main__":
    if len(sys.argv) > 1 and sys.argv[1] == "demo":
        demo()
    else:
        print(__doc__)

